// Reviewed catalog-only adaptation of original AssetVault Add -> spawnObject.
export function attachNativeAssetLibrary({host,signal,onAdd}){
 const doc=host.ownerDocument;let disposed=false,generation=0,current=null;
 host.innerHTML='<h2>Current theme object catalog</h2><p>Add an independent instance at the world center, including after the room is empty. Current theme only; no asset downloads, autoplay or cross-theme imports. Adding explicitly adopts existing instance format v6 if needed.</p><label>Search current theme objects <input type="search" maxlength="200" data-asset-library-search placeholder="Name, shape or role"></label><p data-asset-library-summary aria-live="polite"></p><div data-asset-library-list></div><p role="status" data-asset-library-status></p>';
 const list=host.querySelector('[data-asset-library-list]'),summary=host.querySelector('[data-asset-library-summary]'),status=host.querySelector('[data-asset-library-status]'),search=host.querySelector('[data-asset-library-search]');
 function render(){if(disposed||!current)return;const {key,name,objects,count}=current,token=++generation,terms=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean),matches=objects.filter(o=>{const text=[o.name,o.shape,o.role].map(String).join(' ').toLowerCase();return terms.every(term=>text.includes(term));});summary.textContent=String(name)+' · '+count+'/100 instances · '+matches.length+'/'+objects.length+' catalog objects';list.replaceChildren();for(const o of matches){const row=doc.createElement('div'),label=doc.createElement('span'),button=doc.createElement('button');label.textContent=String(o.name)+' · '+String(o.shape)+' · '+String(o.role)+' ';button.textContent='Add '+String(o.name);button.dataset.addCatalogObject=o.id;button.disabled=count>=100;button.addEventListener('click',()=>{if(disposed||token!==generation||!host.contains(button))return;try{const id=onAdd(key,o.id);status.textContent='Added independent instance '+id+'. Undo removes this addition.';}catch(e){status.textContent=String(e.message||'Add failed; no instance created.');}});row.append(label,button);list.append(row);}if(!matches.length){const empty=doc.createElement('p');empty.textContent='No matching objects in this theme. Change or clear the search.';list.append(empty);}}
 function update({key,name,objects,count}){if(disposed)return;current={key,name,objects,count};render();status.textContent=count>=100?'Instance limit reached. Remove an instance before adding.':'Choose an object to add; existing room content is retained.';}
 function dispose(){if(disposed)return;disposed=true;generation++;current=null;search.removeEventListener('input',render);signal?.removeEventListener('abort',dispose);host.replaceChildren();}search.addEventListener('input',render);signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return{update,dispose};
}
